            down = r+1 < h and grid[r+1][c] == 8
            left = c > 0 and grid[r][c-1] == 8
            right = c+1 < w and grid[r][c+1] == 8
            if left and right and up and down:
                color = 1
            elif left and right:
                color = 1
            elif up and down:
                color = 1
            elif right and down:
                color = 4
            elif left and down:
                color = 3
            elif up and right:
                color = 4
            elif up and left:
                color = 3
            elif right or left:
                color = 2
            else:
                color = 2
            out[r][c] = color
    return out
