def transform(grid):
    # For this task, color connected portions by the repeated 2x2 glyph motif.
    # Tile colors: solid or central tiles=1, upper-left wing=2, lower-left=3,
    # upper-right=4. Partial tiles use the same class by their orientation.
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    for r0 in range(0, h, 2):
        for c0 in range(0, w, 2):
            pts = [(r0+dr, c0+dc) for dr in range(2) for dc in range(2)
                   if r0+dr < h and c0+dc < w and grid[r0+dr][c0+dc] == 8]
            if not pts:
                continue
            s = {(r-r0,c-c0) for r,c in pts}
            if len(s) == 4:
                color = 1
            elif len(s) == 3:
                absent = ({(0,0),(0,1),(1,0),(1,1)} - s).pop()
                color = {(0,0):2,(1,0):3,(0,1):4,(1,1):1}[absent]
            elif len(s) == 2:
                color = 1 if len({r for r,c in s}) == 1 else 1
            else:
                color = 1
            for r,c in pts:
                out[r][c] = color
    return out
