def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    # Infer 2x2 patches and color by the tile's position in the motif.
    for r0 in range(0, h, 2):
        for c0 in range(0, w, 2):
            cells = [(r0+dr, c0+dc) for dr in range(2) for dc in range(2)
                     if r0+dr < h and c0+dc < w and grid[r0+dr][c0+dc] == 8]
            if not cells:
                continue
            shape = {(r-r0,c-c0) for r,c in cells}
            if shape == {(0,0),(0,1),(1,0),(1,1)}:
                color = 1
            elif len(shape) == 3:
                # Three-cell pattern labels: absent TL=2, BL=3, TR=4.
                missing = ({(0,0),(0,1),(1,0),(1,1)} - shape).pop()
                color = {(0,0):2,(1,0):3,(0,1):4,(1,1):1}[missing]
            else:
                color = 1
            for r,c in cells:
                out[r][c] = color
    return out
