def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    # Color 2x2 foreground tiles according to their occupancy pattern.
    full = {(0, 0), (0, 1), (1, 0), (1, 1)}
    missing_color = {(0, 0): 2, (0, 1): 4, (1, 0): 3, (1, 1): 1}
    for r0 in range(0, h, 2):
        for c0 in range(0, w, 2):
            cells = [(r0 + dr, c0 + dc) for dr in range(2) for dc in range(2)
                     if r0 + dr < h and c0 + dc < w and grid[r0 + dr][c0 + dc] == 8]
            shape = {(r - r0, c - c0) for r, c in cells}
            if not shape:
                continue
            if len(shape) == 4:
                color = 1
            elif len(shape) == 3:
                color = missing_color[next(iter(full - shape))]
            else:
                color = 1
            for r, c in cells:
                out[r][c] = color
    return out
